+.pill{display:inline-flex;align-items:center;gap:.35rem;font-size:.72rem;font-weight:600;letter-spacing:.06em;text-transform:uppercase;padding:.15rem .5rem;border-radius:999px;border:1px solid var(--line-strong);color:var(--ink);white-space:nowrap}
+.pill::before{content:"";width:.5rem;height:.5rem;border-radius:50%;background:var(--neutral)}
+.pill.promote::before{background:var(--good)}.pill.reject::before{background:var(--critical)}.pill.running::before{background:var(--running)}
+.tag{display:inline-block;font-size:.7rem;color:var(--muted);border:1px solid var(--line);border-radius:3px;padding:0 .35rem;letter-spacing:.04em}
