+table.matrix td.r4{background:var(--seq-4);color:#fff}table.matrix td.r5{background:var(--seq-5);color:#fff}table.matrix td.r6{background:var(--seq-6);color:#fff}table.matrix td.r7{background:var(--seq-7);color:#fff}
+:root[data-theme="dark"] table.matrix td.r3,:root[data-theme="dark"] table.matrix td.r4{color:#fff}
+:root[data-theme="dark"] table.matrix td.r6,:root[data-theme="dark"] table.matrix td.r7{color:#0b0b0b}
+@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) table.matrix td.r3,:root:not([data-theme="light"]) table.matrix td.r4{color:#fff}:root:not([data-theme="light"]) table.matrix td.r6,:root:not([data-theme="light"]) table.matrix td.r7{color:#0b0b0b}}
+table.matrix td .tier{display:block;font-size:.6rem;color:var(--muted)}
+.toggles{display:flex;gap:.35rem;flex-wrap:wrap}
+button.toggle,button.chip{font:inherit;font-size:.78rem;background:var(--surface);color:var(--ink);border:1px solid var(--line-strong);border-radius:999px;padding:.2rem .7rem;cursor:pointer}
+button.toggle[aria-pressed="true"],button.chip[aria-pressed="true"]{background:var(--accent);color:var(--accent-ink);border-color:var(--accent)}
+/* timeline */
