+.timeline rect.run:hover{stroke:var(--ink);stroke-width:1}
+.timeline .lane{fill:var(--muted);font-size:10.5px}
+/* records table */
+.controls{display:flex;flex-wrap:wrap;gap:.5rem 1rem;align-items:center}
