+    const exp = r.experiment ? [['digest', r.experiment.digest.slice(0, 16)], ['delta', `${signed(r.experiment.delta)} [${r.experiment.interval ? signed(r.experiment.interval.lower) + ', ' + signed(r.experiment.interval.upper) : '–'}]`], ['paired', r.experiment.seedsPaired], ['caps', (r.experiment.caps || []).map(c => c.join(' ')).join('; ') || 'none'], ['cell errors', r.experiment.errors ?? 0]] : []
+    const arms = (r.arms || []).map(a => `<tr><td>${esc(a.label)}</td><td class="num">${a.totals.certified}/${a.totals.cells}</td><td class="num">${a.totals.firstAttempt}</td><td class="num">${a.totals.attemptsMean}</td><td class="num">${fmt(a.totals.secondsMedian)} s</td><td class="num">${fmt(a.totals.outputTokens)}</td><td class="num">${fmt(a.totals.billedTokens)}</td><td class="num">${a.totals.breachedCells}</td></tr>`).join('')
+    const rows = (r.rows || []).map(row => `<tr><td>${esc(row.arm)}</td><td>${esc(row.environment.replace(/^code:/, ''))} <span class="tag">r${row.repetition}</span></td><td>${esc(row.implementer)} · ${esc(row.route)}</td><td class="${row.certified ? 'yes' : 'no'}">${row.certified ? 'yes' : 'no'}</td><td>${attemptsBar(row)}</td><td>${fmt(row.seconds)}</td><td>${fmt(row.steps)}</td><td>${fmt(row.outputTokens)}</td><td>${fmt(row.cacheReadTokens || 0)}</td><td>${fmt(row.cacheWriteTokens || 0)}</td><td>${row.breaches || ''}</td></tr>`).join('')
+    return `<div class="detail-grid"><div class="detail">${r.note ? `<p>${esc(r.note)}</p>` : ''}<dl>${[...dl, ...exp].map(([k, v]) => `<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl>${arms ? `<table class="plain" style="margin-top:.75rem"><thead><tr><th>arm</th><th class="num">certified</th><th class="num">1st</th><th class="num">attempts</th><th class="num">median</th><th class="num">output</th><th class="num">billed</th><th class="num">caps hit</th></tr></thead><tbody>${arms}</tbody></table>` : ''}</div>
+      <div style="overflow-x:auto">${rows ? `<table class="rows"><thead><tr><th>arm</th><th>cell</th><th>route</th><th>cert</th><th>attempts</th><th>secs</th><th>steps</th><th>output</th><th>read</th><th>write</th><th>caps</th></tr></thead><tbody>${rows}</tbody></table>` : '<p class="detail">No cell sessions in this record.</p>'}</div></div>`
+  }
+  function renderRecords() {
+    const kinds = [...new Set(allRecords.map(r => r.kind))]
+    const tiers = [...new Set(allRecords.flatMap(r => r.tiers))].sort()
+    $('record-controls').innerHTML = `<input id="record-search" type="search" placeholder="filter by name, environment, model…" value="${esc(query)}" aria-label="filter records">`
+      + `<span class="toggles">${[['all kinds', null], ...kinds.map(k => [k, k])].map(([l, k]) => `<button class="chip" type="button" data-kind="${k ?? ''}" aria-pressed="${kindFilter === k}">${esc(l)}</button>`).join('')}</span>`
+      + `<span class="toggles">${[['all tiers', null], ...tiers.map(t => ['tier ' + t, t])].map(([l, t]) => `<button class="chip" type="button" data-tier="${t ?? ''}" aria-pressed="${tierFilter === t}">${esc(l)}</button>`).join('')}</span>`
+    $('record-search').addEventListener('input', (e) => { query = e.target.value.toLowerCase(); renderTable() })
+    $('record-controls').querySelectorAll('button[data-kind]').forEach(b => b.addEventListener('click', () => { kindFilter = b.dataset.kind || null; renderRecords() }))
+    $('record-controls').querySelectorAll('button[data-tier]').forEach(b => b.addEventListener('click', () => { tierFilter = b.dataset.tier ? Number(b.dataset.tier) : null; renderRecords() }))
+    renderTable()
+  }
+  function renderTable() {
+    const rows = allRecords.filter(r => (!kindFilter || r.kind === kindFilter) && (!tierFilter || r.tiers.includes(tierFilter)) && (!query || r.search.includes(query)))
+      .sort((a, b) => { const x = a[sortKey], y = b[sortKey]; const c = typeof x === 'number' && typeof y === 'number' ? x - y : String(x ?? '').localeCompare(String(y ?? '')); return c * sortDir })
+    $('records').innerHTML = `<thead><tr>${columns.map(([k, l, t]) => `<th class="${t}" data-key="${k}" aria-sort="${sortKey === k ? (sortDir > 0 ? 'ascending' : 'descending') : 'none'}">${l}</th>`).join('')}</tr></thead><tbody>${rows.map(r => `<tr class="record" data-name="${esc(r.name)}" tabindex="0">${columns.map(([k, , t, f]) => `<td class="${t}">${f(r)}</td>`).join('')}</tr>`).join('')}</tbody>`
+    $('records').querySelectorAll('th').forEach(th => th.addEventListener('click', () => { const k = th.dataset.key; if (sortKey === k) sortDir = -sortDir; else { sortKey = k; sortDir = k === 'ranAt' || k === 'name' ? -1 : -1 } renderTable() }))
+    $('records').querySelectorAll('tr.record').forEach(tr => {
+      const open = () => {
+        const next = tr.nextElementSibling
+        if (next && next.classList.contains('detail')) { next.remove(); tr.classList.remove('open'); return }
+        const r = allRecords.find(x => x.name === tr.dataset.name)
+        const d = document.createElement('tr'); d.className = 'detail'; d.innerHTML = `<td colspan="${columns.length}">${detail(r)}</td>`
+        tr.after(d); tr.classList.add('open')
+      }
+      tr.addEventListener('click', (e) => { if (e.target.closest('a')) return; open() })
+      tr.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); open() } })
+    })
+  }
+  renderRecords()
+
+  // ---- routing + repeatability
+  if (D.readings.routing) {
+    const rs = D.readings.routing.results
+    const max = Math.max(...rs.map(r => r.output))
+    $('routing').innerHTML = `<table class="plain"><thead><tr><th>router</th><th class="num">certified</th><th class="num">output tokens</th><th class="num">steps</th><th class="num">cell time</th></tr></thead><tbody>${rs.map(r => `<tr><td>${esc(r.router)}</td><td class="num">${r.certified}/${r.cells}</td><td class="num"><div class="bar-track" style="display:inline-block;width:7rem;vertical-align:middle;margin-right:.4rem"><div class="bar-fill" style="width:${(r.output / max) * 100}%;background:var(--accent)"></div></div>${fmt(r.output)}</td><td class="num">${fmt(r.steps)}</td><td class="num">${secs(r.secs)}</td></tr>`).join('')}</tbody></table><p style="color:var(--muted);font-size:.8rem;margin:.6rem 0 0">${esc(D.readings.routing.note)}</p>`
+  }
+  if (D.readings.repeatability) {
+    const rp = D.readings.repeatability
+    $('repeatability').innerHTML = `<table class="plain"><thead><tr><th>arms compared</th><th class="num">both</th><th class="num">neither</th><th class="num">flips</th><th class="num">flip rate</th></tr></thead><tbody>${rp.pairs.map(p => `<tr><td>${esc(p.a)} · ${esc(p.b)}</td><td class="num">${p.both}</td><td class="num">${p.neither}</td><td class="num">${p.flips}</td><td class="num">${(p.flipRate * 100).toFixed(1)} %</td></tr>`).join('')}</tbody></table><p style="color:var(--muted);font-size:.8rem;margin:.6rem 0 0">${esc(rp.note)}</p>`
+  }
+
+  // ---- training corpus
+  if (D.dataset) {
+    const ds = D.dataset, c = ds.counts ?? {}, dist = ds.distributions ?? {}
+    $('dataset-section').hidden = false
+    $('dataset-lede').textContent = `${ds.name}: every recorded trajectory folded into one RLVR-ready set, built ${when(ds.builtAt)} from ${ds.records} records. A trajectory's reward is 1 for a certificate and 0 for a run whose checks failed; delegated cells carry no model turns and stay out; tampered runs stay out.`
+    const distBars = (title, entries, colorOf) => {
+      const rows = Object.entries(entries ?? {}).sort((a, b) => b[1] - a[1])
+      const max = Math.max(1, ...rows.map(([, n]) => n))
+      return `<h3>${esc(title)}</h3>` + barChart(rows.map(([k, n]) => ({ label: k, n })), 'n', max, colorOf, r => fmt(r.n))
+    }
+    const rewardColor = (r) => r.label === '1' ? 'var(--good)' : r.label === '0' ? 'var(--critical)' : 'var(--neutral)'
+    const modelColor = (r) => SERIES[D.routeSlots[String(r.label).split('/').pop()] ?? 3]
+    $('dataset').innerHTML = `<div>
+        <div class="stats" style="border:none;padding-block:0 .75rem">${[[c.train, 'trajectories in train'], [c.seen, 'seen'], [c.delegatedExcluded, 'delegated, excluded'], [c.duplicatesDropped, 'duplicates dropped'], [c.tamperedExcluded, 'tampered, excluded'], [c.withheldHeldOut, 'held out, withheld']].map(([n, l]) => `<div class="stat"><b>${fmt(n)}</b><span>${l}</span></div>`).join('')}</div>
+        ${distBars('reward', dist.reward, rewardColor)}
+        <p class="arms" style="margin:.75rem 0 0;color:var(--muted);font-size:.8rem">Tokens over the training steps: ${fmt(ds.tokens?.outputTokens)} output, ${fmt(ds.tokens?.cacheReadTokens)} cache-read, ${fmt(ds.tokens?.cacheWriteTokens)} cache-write, over ${fmt(ds.tokens?.stepsWithUsage)} of ${fmt(ds.tokens?.steps)} steps. Files: ${(ds.files ?? []).map(f => `${esc(f.path)} (${fmt(f.bytes)} bytes)`).join(', ')}.</p>
+      </div>
+      <div class="bars" style="gap:1rem">${distBars('model route', dist.model, modelColor)}${distBars('tier', dist.tier, () => 'var(--accent)')}${distBars('arm', dist.arm, () => 'var(--accent)')}</div>`
+  }
+
+  // ---- notes + footer
+  $('notes').innerHTML = D.notes.map(n => `<p>${n}</p>`).join('')
+  $('footer').innerHTML = `Built by <span class="mono">data/proving-ground/tools/build-dashboard.mjs</span> at ${esc(when(D.builtAt))} from ${D.summary.records} records on <span class="mono">${esc(D.branch)}</span> @ <span class="mono">${esc(D.head.slice(0, 9))}</span>. Records: <a href="${esc(D.linkBase)}data/proving-ground/README.md">README</a> · results: <a href="${esc(D.linkBase)}.agents/notes/proposed/architecture/2026-09-08-hypothesis-program-results.md">hypothesis program</a>.`
+})()
+</script>

